/*
 * Copyright (c) 2024 Croxel Inc.
 *
 * SPDX-License-Identifier: Apache-2.0
 */

#include <zephyr/kernel.h>
#include <zephyr/init.h>
#include <zephyr/rtio/rtio.h>
#include <zephyr/rtio/work.h>

#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(rtio_workq, CONFIG_RTIO_LOG_LEVEL);

#define RTIO_WORKQ_THREADS CONFIG_RTIO_WORKQ_THREADS_POOL
#define RTIO_WORKQ_PRIO_MED CONFIG_RTIO_WORKQ_PRIO_MED

/* Work queue pool */
static struct k_p4wq rtio_workq;

/* Work request pool */
static K_MEM_SLAB_DEFINE(rtio_work_req_slab, sizeof(struct rtio_work_req),
			 RTIO_WORKQ_THREADS, sizeof(void *));

static atomic_t rtio_work_req_used_count;

static void rtio_work_handler(struct k_work *work)
{
	struct rtio_work_req *req = CONTAINER_OF(work, struct rtio_work_req, work);

	if (req->handler && req->iodev_sqe) {
		req->handler(req->iodev_sqe);
	}

	/* Release the work request back to the pool */
	k_mem_slab_free(&rtio_work_req_slab, (void *)req);
	atomic_dec(&rtio_work_req_used_count);
}

struct rtio_work_req *rtio_work_req_alloc(void)
{
	struct rtio_work_req *req = NULL;
	int ret;

	ret = k_mem_slab_alloc(&rtio_work_req_slab, (void **)&req, K_NO_WAIT);
	if (ret == 0) {
		(void)memset(req, 0, sizeof(struct rtio_work_req));
		k_work_init(&req->work, rtio_work_handler);
		atomic_inc(&rtio_work_req_used_count);
	}

	return req;
}

void rtio_work_req_submit(struct rtio_work_req *req, struct rtio_iodev_sqe *iodev_sqe,
			  void (*handler)(struct rtio_iodev_sqe *iodev_sqe))
{
	if (req == NULL) {
		return;
	}

	req->iodev_sqe = iodev_sqe;
	req->handler = handler;

	/* Submit to priority-aware work queue */
	k_p4wq_submit(&rtio_workq, &req->work, iodev_sqe->sqe.prio);
}

int rtio_work_req_used_count_get(void)
{
	return atomic_get(&rtio_work_req_used_count);
}

static int rtio_workq_init(void)
{
	static struct k_p4wq_work_queue worker_threads[RTIO_WORKQ_THREADS];
	static struct k_thread rtio_workq_threads[RTIO_WORKQ_THREADS];
	static K_THREAD_STACK_ARRAY_DEFINE(rtio_workq_stacks, RTIO_WORKQ_THREADS, 512);

	/* Initialize priority-aware work queue */
	k_p4wq_init(&rtio_workq);

	/* Add worker threads */
	for (int i = 0; i < RTIO_WORKQ_THREADS; i++) {
		k_p4wq_add_thread(&rtio_workq, &worker_threads[i], &rtio_workq_threads[i],
				   rtio_workq_stacks[i], K_THREAD_STACK_SIZEOF(rtio_workq_stacks[i]),
				   RTIO_WORKQ_PRIO_MED);
	}

	return 0;
}

SYS_INIT(rtio_workq_init, POST_KERNEL, CONFIG_KERNEL_INIT_PRIORITY_DEFAULT);
EOF"}

